beforeExample:
public class Example {
    public void test() {
        StringBuffer sb = new StringBuffer("hello");
        sb.append(" world");
        System.out.println(sb.toString());
    }
}

afterExample:
public class Example {
    public void test() {
        StringBuilder sb = new StringBuilder("hello");
        sb.append(" world");
        System.out.println(sb.toString());
    }
}

negativeExample:
public class Example {
    private static StringBuffer sharedBuffer = new StringBuffer(); // Field, not local var
    public void test(StringBuffer paramBuffer) { // Parameter, not local var
        sharedBuffer.append("data");
        paramBuffer.append("other data");
        StringBuffer indirectBuffer;
        indirectBuffer = getBuffer(); // Not initialized with 'new' in declaration
    }
    private StringBuffer getBuffer() { return new StringBuffer(); }
}
